/* Development gallery generated by check_player_sprite.cjs --preview --weapons.
   Uses real renderers and isolated fixtures; never loaded by the game. */
(()=>{
 const h=heroPreview,c=document.querySelector('#game'),g=c.getContext('2d');
 const ids=['revolver','shotgun','dynamite','thorns','lasso','rain','meteor','solar'];
 const times={revolver:.035,shotgun:.04,dynamite:.32,thorns:.14,lasso:.14,rain:.07,meteor:.48,solar:.07};
 h.setSound(false);
 function fixture(id){
  h.newGame();const game=h.game,p=game.player;p.x=-535;p.y=-200;
  for(const [x,y] of [[-420,-215],[-365,-165],[-340,-245]]){
   const e=h.spawnEnemy('brute');Object.assign(e,{x,y,hp:5000,maxHp:5000,speed:0});
  }
  const w=game.weapons[id];w.level=1;h.fireWeapon(w);
  if(id==='dynamite')WeaponVisuals.emit(game,'blast',p.x+170,p.y,0,110),game.weaponFx[0].start=.85;
  return {id,game,shots:game.shots.map(s=>({...s}))};
 }
 const fixtures=ids.map(fixture);
 const query=new URLSearchParams(location.search),forcedTime=query.has('time')?Number(query.get('time')):null;
 let animate=query.has('animate'),elapsed=0,last=0,frames=0;
 window.addEventListener('error',e=>document.documentElement.dataset.weaponError=e.message);
 const button=document.createElement('button');button.textContent='Animar / pausar';
 button.style.cssText='position:fixed;right:20px;bottom:20px;padding:10px;background:#ddc18b;border:0;color:#242a32;cursor:pointer';
 document.body.append(button);button.onclick=()=>{animate=!animate};
 function paint(){
  document.documentElement.dataset.weaponFrames=String(++frames);
  g.setTransform(1,0,0,1,0,0);g.imageSmoothingEnabled=false;g.globalAlpha=1;
  g.fillStyle='#242a32';g.fillRect(0,0,c.width,c.height);
  fixtures.forEach((f,i)=>{
   const left=i%4*300,top=Math.floor(i/4)*390,t=animate?elapsed%1.5:forcedTime??times[f.id],game=f.game,p=game.player;
   h.setGame(game);game.time=t;p.attack=Math.max(0,.18-t);p.weaponPose=Math.max(0,.72-t);p.muzzleFlash=Math.max(0,.07-t);
   game.weapons.thorns.angle=t*2;
   game.shots=f.shots.filter(s=>s.life>t).map(s=>({...s,x:s.x+s.vx*t,y:s.y+s.vy*t,life:s.life-t}));
   for(const hazard of game.hazards){hazard.t=t;hazard.done=t>=hazard.delay}
   g.save();g.beginPath();g.rect(left,top,298,388);g.clip();g.translate(left,top);
   g.fillStyle=i%2?'#2d3338':'#303637';g.fillRect(0,0,298,388);
   g.fillStyle='#e5ce9e';g.font='bold 16px monospace';g.textAlign='left';g.fillText(game.weapons[f.id].name,14,28);
   g.font='12px monospace';g.fillStyle='#a9b5ac';g.fillText('t = '+t.toFixed(2)+' s',14,49);
   for(const hazard of game.hazards)WeaponVisuals.meteor(g,hazard,x=>x+600,y=>y+400);
   WeaponVisuals.orbits(g,game,x=>x+600,y=>y+400);
   for(const e of game.enemies)h.drawEnemy(e);
   h.drawPlayer(p);
   for(const shot of game.shots)h.drawProjectileSprite(shot);
   WeaponVisuals.effects(g,game,x=>x+600,y=>y+400);h.drawLassoEffects();
   g.restore();
  });
 }
 function tick(now){if(last&&animate){elapsed+=Math.min(.05,(now-last)/1000);paint()}last=now;requestAnimationFrame(tick)}
 window.addEventListener('resize',paint);paint();requestAnimationFrame(tick);
})();
